const itemsToShow = computed(() => props.items ?? [])

const track = ref<HTMLElement | null>(null)
const itemEls = ref<HTMLElement[]>([])
const current = ref(0)
const spacer = ref(0)

function centerToIndex(i, behavior = 'smooth') {
    const el = track.value, item = itemEls.value[i]
    if (!el || !item) return
    const offset = item.offsetLeft - (el.clientWidth - item.offsetWidth) / 2
    el.scrollTo({ left: offset, behavior })
}

function nearestIndex() {
    const el = track.value
    if (!el) return 0
    const mid = el.scrollLeft + el.clientWidth / 2
    let best = 0, dist = Infinity
    itemEls.value.forEach((it, i) => {
        const c = it.offsetLeft + it.offsetWidth / 2
        const d = Math.abs(c - mid)
        if (d < dist) { dist = d; best = i }
    })
    return best
}
function updateCurrent() { current.value = nearestIndex() }
let dragging = false, startX = 0, startLeft = 0
function onPointerDown(e) {
    dragging = true
    startX = e.clientX
    startLeft = track.value?.scrollLeft ?? 0
    track.value?.setPointerCapture?.(e.pointerId)
}
function onPointerMove(e) {
    if (!dragging || !track.value) return
    const dx = e.clientX - startX
    track.value.scrollLeft = startLeft - dx
}
function onPointerUp(e) {
    dragging = false
    track.value?.releasePointerCapture?.(e.pointerId)
    centerToIndex(nearestIndex())
}
function onPointerCancel(e) {
    dragging = false
    track.value?.releasePointerCapture?.(e.pointerId)
    centerToIndex(nearestIndex())
}
function recomputeSpacer() {
    const el = track.value
    const first = itemEls.value?.[0]
    if (!el || !first) return
    const w = first.offsetWidth
    // metade do espaço livre do viewport
    spacer.value = Math.max(0, (el.clientWidth - w) / 2)
    // recenter no atual sem animação
    centerToIndex(current.value, 'auto')
}
let ro, ticking = false
function onScroll() {
    if (ticking) return
    ticking = true
    requestAnimationFrame(() => { updateCurrent(); ticking = false })
}

onMounted(async () => {
    await nextTick()
    recomputeSpacer()
    ro = new ResizeObserver(recomputeSpacer)
    ro.observe(track.value)
})
onBeforeUnmount(() => ro?.disconnect?.())
</script>

<template>
  <div
    ref="track"
    class="w-full max-w-[1150px] flex md:gap-6 lg:gap-10 overflow-x-auto scroll-smooth
           snap-x snap-mandatory select-none cursor-grab active:cursor-grabbing scrollbar-hide"
    @pointerdown="onPointerDown"
    @pointermove="onPointerMove"
    @pointerup="onPointerUp"
    @pointercancel="onPointerCancel"
    @scroll.passive="onScroll"
  >
    <!-- spacers nas pontas -->
    <div class="shrink-0" />

    <!-- AGORA USANDO itemsToShow E 2 ITENS POR VEZ -->
    <div
      v-for="(t, i) in itemsToShow"
      :key="i"
      :ref="el => (itemEls[i] = el)"
      class="shrink-0 w-[50%] md:w-1/2 lg:w-1/2 snap-center"
    >
      <div
        class="w-full h-full bg-[#370F1E] rounded-xl flex flex-col items-center justify-between pt-[10px] pb-[10px] px-6
               lg:py-[30px] lg:px-[30px]"
      >
        <div
            class="mt-4"
            v-html="t.svg"
            />
        <!-- TÍTULO -->
        <p
          class="text-[#fff] font-crossfit font-bold 
                 text-[17px] lg:text-[26px] leading-[1.2]"
        >
          {{ t.title }}
        </p>
        <p
          class="text-[#fff] px-[5px] font-DMSans text-center text-[13px] lg:text-[18px] max-w-[140px] leading-[1.3] mt-2"
        >
          {{ t.subtitle }}
        </p>
      </div>
    </div>

    <div class="shrink-0" :style="{ width: spacer + 'px' }" />
  </div>

  <!-- bolinhas de navegação -->
  <svg
    :width="6 + (itemsToShow.length - 1) * 12"
    height="6"
    :viewBox="`0 0 ${6 + (itemsToShow.length - 1) * 12} 6`"
    fill="none"
    class="mt-3 lg:mt-[5.5rem]"
  >
    <g
      v-for="(_, i) in itemsToShow"
      :key="`dot-${i}`"
      @click="centerToIndex(i)"
      class="cursor-pointer"
    >
      <circle
        :cx="3 + i * 12"
        cy="3"
        r="3"
        :fill="i === current ? '#961D4A' : '#FFFAF0'"
      />
    </g>
  </svg>
</template>
